(() => {
  // Page-coordinate lasso around a digit's main blob: the convex hull of its anchors near their median.
  const codes = a.labelCodesAnchors, xy = a.anchorXY, g = a.labelMeta.categories.indexOf('1');
  const vp = a.renderer.deck.getViewports()[0], r = document.querySelector('.plot').getBoundingClientRect();
  let pts = [];
  for (let i = 0; i < codes.length; i++) if (codes[i] === g) pts.push(vp.project([xy[2 * i], xy[2 * i + 1]]));
  const med = k => pts.map(p => p[k]).sort((u, v) => u - v)[pts.length >> 1];
  const cx = med(0), cy = med(1);
  const d = pts.map(p => Math.hypot(p[0] - cx, p[1] - cy));
  const dm = [...d].sort((u, v) => u - v)[d.length >> 1];
  pts = pts.filter((p, i) => d[i] < 2.5 * dm).sort((p, q) => p[0] - q[0] || p[1] - q[1]);
  const cross = (o, p, q) => (p[0] - o[0]) * (q[1] - o[1]) - (p[1] - o[1]) * (q[0] - o[0]);
  const lower = [], upper = [];
  for (const p of pts) { while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) lower.pop(); lower.push(p); }
  for (const p of [...pts].reverse()) { while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) upper.pop(); upper.push(p); }
  const hull = lower.slice(0, -1).concat(upper.slice(0, -1));
  return hull.map(([x, y]) => { const k = Math.hypot(x - cx, y - cy) || 1; return [r.left + x + 6 * (x - cx) / k, r.top + y + 6 * (y - cy) / k]; });
})()

